function applyMediaOverrides(){
 media=structuredClone(EMBEDDED_MEDIA);
 for(const [id,clip] of Object.entries(mediaOverrides.audio)){if(clip===null)delete media.audio[id];else media.audio[id]=clip;}
 if(mediaOverrides.video){media.video=mediaOverrides.video;media.poster='';}
}
function persistMedia(){
 const snapshot=structuredClone(mediaOverrides);
 mediaWritePromise=mediaWritePromise.then(()=>LessonStorage.put(MEDIA_KEY,snapshot),()=>LessonStorage.put(MEDIA_KEY,snapshot));
 return mediaWritePromise.then(ok=>{mediaStoreStatus=ok?'saved':'unavailable';refreshReadiness();return ok;});
}
async function hydrateMedia(){
 const result=await LessonStorage.get(MEDIA_KEY);mediaStoreStatus=result.ok?'available':'unavailable';
 if(result.ok&&result.value&&!mediaTouched){mediaOverrides=Core.mediaPatch(result.value);applyMediaOverrides();if(Object.keys(mediaOverrides.audio).length||mediaOverrides.video)mediaStoreStatus='saved';const v=$('#teacherVideo');if(v&&v.paused&&v.currentTime===0){v.src=media.video;v.poster=media.poster;}}
 refreshReadiness();
}
function audioSourceLabel(){const route=Core.audioRoute(data.meta.welcome,media.audio.intro,!!chooseVoice(),audioMode);return {embedded:'تسجيل مضمّن',device:'صوت الجهاز العربي',external:'تسجيل عبر الإنترنت',unavailable:'يحتاج إلى صوت عربي أو تسجيل'}[route];}
function refreshReadiness(){
 const a=$('#readyAudio');if(a)a.textContent=audioSourceLabel();
 const m=$('#readyMedia');if(m)m.textContent=mediaStoreStatus==='saved'?'تعديلات الوسائط محفوظة':mediaStoreStatus==='available'?'متاح على هذا المتصفح':mediaStoreStatus==='loading'?'جارٍ الفحص':'نزّل نسخة للاحتفاظ بالتعديلات';
 const v=$('#readyVideo');if(v)v.textContent=media.video.startsWith('data:video/')?'الفيديو مضمّن':'يحتاج إلى اتصال';
}
function probeMedia(src,kind){
 return new Promise((resolve,reject)=>{
  const el=document.createElement(kind);el.preload='metadata';let ended=false;
  const finish=(error)=>{if(ended)return;ended=true;clearTimeout(timer);el.onloadedmetadata=null;el.onerror=null;el.removeAttribute('src');el.load();error?reject(error):resolve();};
  const timer=setTimeout(()=>finish(Error('تعذّر التحقق من الملف. اختر تسجيلًا أو فيديو بصيغة يدعمها المتصفح.')),8000);
  el.onloadedmetadata=()=>{if(!Number.isFinite(el.duration)||el.duration<=0)finish(Error('الملف لا يحتوي على مدة قابلة للتشغيل.'));else finish();};
  el.onerror=()=>finish(Error('المتصفح لم يستطع قراءة الملف. اختر ملفًا سليمًا بصيغة MP3 للصوت أو MP4 للفيديو.'));
  el.src=src;el.load();
 });
}
function editorBusy(on){
 mediaBusy=on;
 $$('#editorDialog input,#editorDialog textarea,#editorDialog select,#editorDialog button').forEach(el=>{
  if(on){if(!el.hasAttribute('data-before-busy'))el.setAttribute('data-before-busy',String(el.disabled));el.disabled=true;}
  else if(el.hasAttribute('data-before-busy')){el.disabled=el.getAttribute('data-before-busy')==='true';el.removeAttribute('data-before-busy');}
 });
 const status=$('#mediaStatus');if(status){status.hidden=!on;status.textContent=on?'جارٍ التحقق من الوسائط وحفظها…':'';}
}
