 if(a==='quiz-start'){stopSpeech();stopTimer();quizCount=Number($('#quizCount').value);activeQ=Core.selectQuestions(data.questions,quizCount);quizStarted=true;quizDone=false;qi=0;answers={};render(true);readCurrentQuestion();return;}
