 if(a==='go-build'){go(7);return;}if(a==='back-quiz'){go(6);return;}if(a==='build-set'){buildSet=n;buildOrder=[];buildChecked=false;buildSuccess=false;stopSpeech();render();return;}if(a==='add-word'){if(buildOrder.length<3&&!buildOrder.includes(n))buildOrder.push(n);buildChecked=false;render();return;}if(a==='remove-word'){buildOrder.splice(n,1);buildChecked=false;render();return;}if(a==='build-clear'){buildOrder=[];buildChecked=false;render();return;}if(a==='build-check'){buildSuccess=Core.isOrder(buildOrder,[0,1,2]);buildChecked=true;if(buildSuccess){buildCompleted.add(buildSet);celebrate();}render();if(autoNarrate)feedbackSound(buildSuccess);announce(buildSuccess?'جملة صحيحة حسب النمط المطلوب.':'هذا ليس ترتيب النشاط المطلوب. جرّب من جديد.');return;}
